using System.Net;using System.Text;using PowerXPlugin.Framework.Runtime.Common;using PowerXPlugin.Framework.Runtime.PluginRuntime;using Xunit;
namespace PowerXPlugin.Framework.Tests.Runtime.PluginRuntime;public sealed class PluginRuntimeTests{const string T="00000000-0000-4000-8000-000000000001";[Fact]public async Task Delegated_uses_tenant_route_and_rejects_override(){HttpRequestMessage? seen=null;var c=new PowerXPluginRuntimeClient("https://core",T,new StaticServiceCredentialProvider(new ServiceCredential("sts")),new HttpClient(new H(r=>{seen=r;return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"data\":{\"items\":[],\"pagination\":{\"total\":0,\"page\":1,\"page_size\":50}}}",Encoding.UTF8)};})));await c.ListKnowledgeSpacesAsync(new(T),new());Assert.Equal("/api/v1/tenant/plugin-runtime/knowledge-spaces",seen!.RequestUri!.AbsolutePath);Assert.Equal("Bearer sts",seen.Headers.Authorization!.ToString());var e=await Assert.ThrowsAsync<PluginRuntimeException>(()=>c.ListKnowledgeSpacesAsync(new("00000000-0000-4000-8000-000000000002"),new()));Assert.Equal(PluginRuntimeErrors.TenantMismatch,e.Code);}sealed class H(Func<HttpRequestMessage,HttpResponseMessage>f):HttpMessageHandler{protected override Task<HttpResponseMessage>SendAsync(HttpRequestMessage r,CancellationToken c)=>Task.FromResult(f(r));}}
